    if hasattr(sys, 'set_int_max_str_digits'):
        sys.set_int_max_str_digits(0)
    n = int(text)
    if n <= 3:
        return str(n - 1)
    (q, r) = divmod(n, 3)
    return str(3 ** q if r == 0 else 4 * 3 ** (q - 1) if r == 1 else 2 * 3 ** q)
