"""管理员题意的独立复算；只在临时目录读取原文，不包含题面或后台测试。"""
import sys,math,random,itertools,heapq,bisect,json,re
from pathlib import Path
from fractions import Fraction
from collections import Counter,defaultdict,deque
from html.parser import HTMLParser
NUMBERS=[18208,18210,18221,21433,21457,21470,21471,21472,21533,21534,21552,21555,21726,23557,23561,23567,25564,25574,27308,27309]
class Text(HTMLParser):
 def __init__(self):super().__init__();self.parts=[]
 def handle_data(self,data):self.parts.append(data)
def plain(value):
 p=Text();p.feed(value);return ''.join(p.parts).replace('\r','')
def statement(n):return json.loads(Path(f'/tmp/gmyhf-admin-statements/{n}.json').read_text())
def samples(n):
 f=statement(n)['fields'];a,b=plain(f['sampleInput']).strip(),plain(f['sampleOutput']).strip()
 if n in (25564,27308,27309):return [(a,b.split('解释')[0].strip())]
 # 两个字段常分别包含一整组输入、输出；只提取明确的标记，不猜测说明文字。
 if n==18210:
  result=[]
  for value in (a,b):
   chunks=re.split(r'Sample[ \t]*Input[ \t]*[0-9]+[ \t]*[:：]?[ \t]*',value)[1:]
   for i in range(0,len(chunks)-1,2):result.append((chunks[i].strip(),chunks[i+1].split('解释')[0].strip()))
  return result
 pairs=[]
 for value in (a,b):
  marks=list(re.finditer(r'(?:Sample|sample|样例)[ \t]*\d*[ \t]*(Input|Output|in|out|输入|输出)[ \t]*\d*[ \t]*[:：]?[ \t]*',value))
  if not marks:continue
  for i,m in enumerate(marks[:-1]):
   if m.group(1).lower() not in ('input','in','输入'):continue
   following=marks[i+1]
   if following.group(1).lower() not in ('output','out','输出'):continue
   given=value[m.end():following.start()].strip();end=marks[i+2].start() if i+2<len(marks) else len(value);want=re.split(r'(?:\n#[ \t]*)?(?:解释|说明)',value[following.end():end],maxsplit=1)[0].strip();pairs.append((given,want))
