NO_SAMPLES={18210:'原样例将输出也标为Input，另以同一字段中可明确分隔的说明人工解析'}
def matrix_gap(text):
 t=text.split();m,n,k=map(int,t[:3]);x=list(map(Fraction,t[3:]));a=[x[i*n:(i+1)*n] for i in range(m)];b=[x[m*n+i*k:m*n+(i+1)*k] for i in range(n)];total=Fraction(0)
 for i in range(m):
  for j in range(k):total+=(sum(a[i][r]*b[r][j] for r in range(n))-max(min(a[i][r],b[r][j]) for r in range(n)))**2
 q,r=divmod(total.numerator*100,total.denominator);q+=2*r>=total.denominator;return f'{q//100}.{q%100:02d}'
def jumps(text):
 x=list(map(int,text.split()));m,n=x[:2];a=x[2:];end=0
 for _ in range(n):end=min(m-1,max(i+a[i] for i in range(end+1)))
 return str(end)
def cipher(text):
 k,line=text.split('\n',1);k=int(k);line=line.rstrip('\r\n');converted=''.join(chr((ord(c)-97+k)%26+65) if 'a'<=c<='z' else c for c in line);return ' '.join(converted.split(' ')[::-1])
def orders(text):
 if hasattr(sys,'set_int_max_str_digits'):sys.set_int_max_str_digits(0)
 x=list(map(int,text.split()));product=1;out=[]
 for value in x[1:]:product*=value;out.append(str(len(str(product))-1))
 return '\n'.join(out)
def gomoku(text):
 lines=text.split();n=int(lines[0]);board=lines[1:];directions=[(0,1),(1,0),(1,1),(1,-1)]
 for i in range(n):
  for j in range(n):
   if board[i][j]!='*':continue
   for di,dj in directions:
    count=1
    for sign in (-1,1):
     u,v=i+sign*di,j+sign*dj
     while 0<=u<n and 0<=v<n and board[u][v]=='w':count+=1;u+=sign*di;v+=sign*dj
    if count>=5:return 'yes'
 return 'no'
def fruit(text):
 n,s=text.split();n=int(n);c=Counter(s);top=max(c.values());return str(max(len(s),(top-1)*(n+1)+sum(v==top for v in c.values())))
def attention(text):
 x=list(map(int,text.split()));n=x[0];a=[x[1+i*n:1+(i+1)*n] for i in range(n)];gram=[[sum(a[i][r]*a[j][r] for r in range(n)) for j in range(n)] for i in range(n)];return '\n'.join(' '.join(str(sum(gram[i][r]*a[r][j] for r in range(n))) for j in range(n)) for i in range(n))
def boxes(text):
 x=list(map(int,text.split()));rows=sorted(zip(x[1::2],x[2::2]),key=lambda q:(q[0],-q[1]));tails=[]
 for _,b in rows:
  at=bisect.bisect_left(tails,b)
  if at==len(tails):tails.append(b)
  else:tails[at]=b
 return str(len(tails))
def clicks(text):
 t=text.split();starts=set(t[1::2]);ends=set(t[2::2]);return next(iter(ends-starts))
def effort(text):
 x=list(map(int,text.split()));n,m=x[:2];a=x[2:];d=[math.inf]*(n*m);d[0]=0;heap=[(0,0)]
 while heap:
  val,i=heapq.heappop(heap)
  if val!=d[i]:continue
  if i==n*m-1:return str(val)
  r,c=divmod(i,m)
  for u,v in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if 0<=u<n and 0<=v<m:
    j=u*m+v;w=max(val,abs(a[i]-a[j]))
    if w<d[j]:d[j]=w;heapq.heappush(heap,(w,j))
def address(text):
