def apples(text):
 if hasattr(sys,'set_int_max_str_digits'):sys.set_int_max_str_digits(0)
 n=int(text)
 if n<=3:return str(n-1)
 q,r=divmod(n,3);return str(3**q if r==0 else 4*3**(q-1) if r==1 else 2*3**q)
def cyber(text):
 n,a,b=map(int,text.split());return 'yes' if 2**n>a+b else 'no'
def ai(text):
 lines=text.splitlines();n=int(lines[0]);words=defaultdict(list)
 for line in lines[1:n+1]:a,b=line.split();words[a].append(b)
 for a in words:words[a].sort()
 counts=Counter();out=[]
 for line in lines[n+2:n+2+int(lines[n+1])]:
  a=line[len('What is '):-1];options=words[a];b=options[counts[a]%len(options)] if options else a;counts[a]+=1;out.append(f'{a} is {b}.')
 return '\n'.join(out)
def depressions(text):
 x=list(map(int,text.split()));n,m=x[:2];a=x[2:];low=set()
 for i,v in enumerate(a):
  r,c=divmod(i,m)
  if all(v<=a[u*m+w] for u,w in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=u<n and 0<=w<m):low.add(i)
 heights=[a[i] for i in low];sizes=[]
 while low:
  start=low.pop();stack=[start];count=0
  while stack:
   i=stack.pop();count+=1;r,c=divmod(i,m)
   for u,v in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
    if 0<=u<n and 0<=v<m and u*m+v in low:low.remove(u*m+v);stack.append(u*m+v)
  sizes.append(count)
 return f'{len(sizes)} {max(heights) if heights else -1} {max(sizes) if sizes else -1}'
def wealth(text):
 x=list(map(int,text.split()));at=0;out=[]
 while x[at]:
  n=x[at];at+=1;a=[x[at+i*n:at+(i+1)*n] for i in range(n)];at+=n*n;best=sum(max(row) for row in a)
  def visit(i,sums):
   nonlocal best
   if max(sums)>=best:return
   if i==n:best=max(sums);return
   for shift in range(n):visit(i+1,[sums[j]+a[i][(j-shift)%n] for j in range(n)])
  # 所有行共同平移不改变目标，固定首行节省一个因子n。
  visit(1,a[0]);out.append(str(best))
 return '\n'.join(out)
def gamma(text):
 bits=bin(int(text))[2:];return '1'*(len(bits)-1)+'0'+bits[1:]
def birthdays(text):
 x=list(map(int,text.split()));n=x[0];order=x[1:1+n];days=list(zip(x[1+n::2],x[2+n::2]));a=[days[i-1] for i in order];up=sum(a[i]>a[j] for i in range(n) for j in range(i+1,n));down=sum(a[i]<a[j] for i in range(n) for j in range(i+1,n));return str(min(up,down))
def fence(text):
 a,b,c,d=map(int,text.split());return str(b-a+d-c-max(0,min(b,d)-max(a,c)))
def moo(text):
 t=text.split();out=[]
 for s in t[1:]:
  choices=[len(s)-3+(s[i]!='M')+(s[i+2]!='O') for i in range(len(s)-2) if s[i+1]=='O'];out.append(str(min(choices) if choices else -1))
